# -*- coding: utf-8 -*-
# 括线判据估高：wlen（全角1·ASCII0.5，剔\命令）/23，est=ceil，>8 → 括线模
import re, math

G = {}
G['G1'] = r"""焦点 \(F(3/2,0)\)．所求直线过焦点且与抛物线交于两点，可设 \(x=my+3/2\)（\(m\in R\)，\(m=0\) 即竖直线）．代入 \(y^{2}=6x\)：\(y^{2}-6my-9=0\)，\(\Delta=36m^{2}+36>0\) 恒成立，恒交于两点．\(x_{1}+x_{2}=m(y_{1}+y_{2})+3=m\cdot 6m+3=6m^{2}+3=3\)，得 \(m^{2}=0\)、\(m=0\)．故直线唯一：\(x=3/2\)，条数为 1，选 B．（验算：\(x=3/2\) 代入 \(y^{2}=6x\) 得 \(y^{2}=9\)，两交点 \(A(3/2,3)\)、\(B(3/2,-3)\)，\(x_{1}+x_{2}=3\) \ding{51}（此即通径位置）．）"""
G['G2'] = r"""\(a^{2}=2\)，\(2a=2\sqrt{2}\)．\(A\) 在左支：\(|AF_{2}|-|AF_{1}|=2a\)；\(B\) 在右支：\(|BF_{1}|-|BF_{2}|=2a\)．设 \(|AF_{2}|=|BF_{2}|=t\)，则 \(|AF_{1}|=t-2a\)、\(|BF_{1}|=t+2a\)．\(F_{1}(-\sqrt{6},0)\) 在左支顶点 \((-\sqrt{2},0)\) 的左方（位于左支凹侧内），过 \(F_{1}\) 的弦自 \(F_{1}\) 出发先遇左支点 \(A\)、再遇右支点 \(B\)，故 \(|AB|=|BF_{1}|-|AF_{1}|=4a=4\sqrt{2}\)．在 \(\mathrm{Rt}\triangle AF_{2}B\)（\(\angle AF_{2}B=90^{\circ}\)）中：\(|AF_{2}|^{2}+|BF_{2}|^{2}=|AB|^{2}\)，即 \(2t^{2}=(4\sqrt{2})^{2}=32\)，\(t^{2}=16\)，\(t=4\)（\(t>0\)）．故 \(|AF_{2}|=4\)，选 C．（验算：\(t=4\)：\(|AF_{1}|=4-2\sqrt{2}>0\) \ding{51}；\(|AB|=|BF_{1}|-|AF_{1}|=(4+2\sqrt{2})-(4-2\sqrt{2})=4\sqrt{2}\) \ding{51}；勾股 \(2\times 4^{2}=32=(4\sqrt{2})^{2}\) \ding{51}．）"""
G['G3'] = r"""\(a=4\)，\(2a=8\)．\(F_{2}\) 在椭圆内部，弦 \(AB\) 过 \(F_{2}\)，故 \(F_{2}\) 在 \(A\)、\(B\) 之间，\(|AF_{2}|+|BF_{2}|=|AB|\)．\(\triangle ABF_{1}\) 的周长 \(|AB|+|AF_{1}|+|BF_{1}|=(|AF_{1}|+|AF_{2}|)+(|BF_{1}|+|BF_{2}|)=2a+2a=16\)（椭圆定义，与弦的位置无关）．由 \(|AB|+|AF_{1}|=10\) 得 \(|BF_{1}|=16-10=6\)，选 C．（验算：\(|BF_{1}|=6\) 落在焦半径范围 \([a-c,a+c]=[4-\sqrt{7},4+\sqrt{7}]\approx[1.35,6.65]\) 内 \ding{51}；周长恒等 \(4a\) 不依赖过焦弦的方向 \ding{51}．）"""
G['G4'] = r"""设 \(A(x_{1},y_{1})\)、\(B(x_{2},y_{2})\)（\(y_{1}>0>y_{2}\)），直线 \(x=my+p/2\) 代入 \(y^{2}=2px\)：\(y^{2}-2pmy-p^{2}=0\)，得 \(y_{1}y_{2}=-p^{2}\)．由抛物线定义及 \(y_{1}^{2}=2px_{1}\)：\(|AF|=x_{1}+p/2=(y_{1}^{2}+p^{2})/(2p)\)，同理 \(|FB|=(y_{2}^{2}+p^{2})/(2p)\)．\(|AF|=2|FB|\) 即 \(y_{1}^{2}+p^{2}=2(y_{2}^{2}+p^{2})\)，得 \(y_{1}^{2}=2y_{2}^{2}+p^{2}\)．两边乘 \(y_{2}^{2}\) 并以 \((y_{1}y_{2})^{2}=p^{4}\) 代入：\(p^{4}=2y_{2}^{4}+p^{2}y_{2}^{2}\)．令 \(u=y_{2}^{2}\)：\(2u^{2}+p^{2}u-p^{4}=0\)，因式分解 \((2u-p^{2})(u+p^{2})=0\)，\(u>0\) 得 \(u=p^{2}/2\)，即 \(y_{2}^{2}=p^{2}/2\)（此时 \(y_{2}=-p/\sqrt{2}\)、\(y_{1}=\sqrt{2}p=-2y_{2}\) \ding{51}）．\(C(-p/2,0)\)、\(F(p/2,0)\)，\(|CF|=p\)，\(B\) 到 \(x\) 轴距离 \(|y_{2}|=p/\sqrt{2}\)，故 \(S_{\triangle CBF}=\frac{1}{2}\cdot p\cdot p/\sqrt{2}=p^{2}/(2\sqrt{2})=4\sqrt{2}\)，得 \(p^{2}=16\)、\(p=4\)，通径长 \(2p=8\)．（验算：\(p=4\)：\(C(-2,0)\)、\(F(2,0)\)、\(|y_{2}|=2\sqrt{2}\)，\(S=\frac{1}{2}\times 4\times 2\sqrt{2}=4\sqrt{2}\) \ding{51}；\(|AF|=(32+16)/8=6\)、\(|FB|=(8+16)/8=3\)，\(6=2\times 3\) \ding{51}．）"""
G['G5'] = r"""\(P(2,1)\)：\(4/2-1=1\) \ding{51}，\(P\) 在 \(C\) 上．设切线 \(l\)：\(y-1=k(x-2)\)，即 \(y=kx+(1-2k)\)．代入 \(x^{2}/2-y^{2}=1\)（乘 2）：\(x^{2}-2(kx+1-2k)^{2}=2\)，整理得 \((1-2k^{2})x^{2}-4k(1-2k)x-2[(1-2k)^{2}+1]=0\)．若 \(1-2k^{2}=0\)（\(k=\pm\sqrt{2}/2\)），方程降为一次，\(l\) 平行于渐近线 \(y=\pm(\sqrt{2}/2)x\) 而与 \(C\) 仅一个公共点，非切线，排除．故 \(1-2k^{2}\neq 0\)，\(l\) 与 \(C\) 相切即 \(\Delta=0\)：\par\noindent \(\Delta=16k^{2}(1-2k)^{2}+8(1-2k^{2})[(1-2k)^{2}+1]=0\)，除以 8 并展开（\((1-2k)^{2}=1-4k+4k^{2}\)）：\(2k^{2}(1-4k+4k^{2})+(1-2k^{2})(2-4k+4k^{2})=(2k^{2}-8k^{3}+8k^{4})+(2-4k+8k^{3}-8k^{4})=2k^{2}-4k+2=2(k-1)^{2}=0\)，\par\noindent 得 \(k=1\)（\(1-2\times 1=-2\neq 0\)，保持二次 \ding{51}）．故切线方程为 \(y=x-1\)．（验算：\(y=x-1\) 代入：\(x^{2}/2-(x-1)^{2}=1\) 即 \(-x^{2}/2+2x-2=0\)，亦 \(x^{2}-4x+4=0\)、\((x-2)^{2}=0\)，重根 \(x=2\)，切点即 \(P(2,1)\) \ding{51}——恰一公共点且不平行渐近线，为真切线；源解以导数求斜率系后置工具，本解改走联立 \(\Delta=0\)，读数一致．）"""

for k in ['G1','G2','G3','G4','G5']:
    s = G[k]
    s2 = re.sub(r'\\[A-Za-z]+\*?(\{[^{}]*\})*', '', s)  # 剔\命令（含一个花括号参数）
    s2 = s2.replace(r'\(', '').replace(r'\)', '')
    w = 0.0
    for ch in s2:
        w += 1.0 if ord(ch) > 0x2E7F else 0.5
    est = math.ceil(w / 23)
    print(k, 'wlen=%.1f' % w, 'est=', est, '→', '括线模' if est > 8 else '灰底')
